from __future__ import absolute_import
from hran_file_operations.parsers.scfc.base import UniversalScfcParser


class SbtsScfcParser(UniversalScfcParser):
    """
    SBTS-specific implementation of SCFC Parser.
    """
    tech_to_cell_mapping = {"NR": "NRCELL", "LTE": "LNCEL", "WCDMA": "WNCEL", "GSM": "GNCEL"}

    @property
    def cells(self):
        """
        Cells in given scfc
        :return: Dictionary of cells in given scfc,
        slitted into technologies as keys and list of cells as values.
        """
        cells = {}
        for tech, dist_name in self.tech_to_cell_mapping.items():
            if tech == "LTE":
                cells[tech] = [cell for cell in
                               self.get_managed_objects(dist_name) if
                               not self._is_iot(cell.node_obj)]
            else:
                cells[tech] = self.get_managed_objects(dist_name)
        return cells

    def _is_iot(self, cell_node):
        """
        Check if cell is iot
        """
        return bool(cell_node.xpath(
            './/*[@name="cellTechnology"][text()="NB-IoT-FDD"]'))
